def shortest_path_length(graph, start, target):
    if start == target: return 0
    queue = deque([(start, 0)])
    visited = {start}
    while queue:
        curr, dist = queue.popleft()
        if curr == target: return dist
        for nxt in graph.get(curr, []):
            if nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, dist + 1))
    return -1
